import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = (pkg.get('requestedVersion',''), pkg.get('resolvedVersion',''))
        result[name] = pkgs
    return result

before = extract(b)
after = extract(a)

print('=== CHANGES ===')
for proj in sorted(set(list(before.keys()) + list(after.keys()))):
    bp = before.get(proj, {})
    ap = after.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            print(f'{proj}: {pkg} {bv} -> {av}')

print('=== UNCHANGED ===')
for proj in sorted(before.keys()):
    bp = before.get(proj, {})
    ap = after.get(proj, {})
    for pkg in sorted(bp.keys()):
        if bp.get(pkg) == ap.get(pkg):
            print(f'{proj}: {pkg} {bp[pkg]}')
